import { CreativeCard } from '@/react/components/site/CreativeCard'
import { useCaseAnswerCallsLabel, useCaseAnswerChat, type AnswerExample } from '@/lib/use-case-answer'
import { cn } from '@/react/lib/cn'

// The site's use case answer (pages/UseCasesPage/UseCaseAnswer): one question and the answer that came back, on the
// raised panel. In chat mode the question sits in a bubble at the right; in api mode the request shows as code (it
// scrolls sideways, fading at its edges). Then the status, the lead, a table of rows (a creative, a title with its
// detail, a figure), a note and the tools called. Nothing moves.
export interface UseCaseAnswerProps {
  example?: AnswerExample
  /** The label before the calls ("Called"). */
  callsLabel?: string
  className?: string
}

export function UseCaseAnswer({ example: e = useCaseAnswerChat, callsLabel = useCaseAnswerCallsLabel, className }: UseCaseAnswerProps) {
  const api = e.mode === 'api'
  const [itemLabel, figureLabel] = e.columns
  const hasFigure = e.rows.some((r) => r.figure)
  const last = e.rows.length - 1
  return (
    <div data-ds="use-case-answer" data-mode={e.mode} className={cn('flex flex-col gap-6 rounded-panel bg-surface-raised p-4 text-fg md:gap-8 md:p-8', className)}>
      {api && e.request ? (
        <pre tabIndex={0} className="fade-x m-0 overflow-x-auto rounded-ds-sm bg-surface p-4 font-code type-ui text-fg-soft md:p-6"><code>{e.request}</code></pre>
      ) : (
        <p className="max-w-[88%] self-end rounded-ds-lg bg-surface-inset px-4 py-3 type-body text-pretty">
          {e.mention ? <><span className="font-medium">{e.mention}</span> </> : null}
          {e.question}
        </p>
      )}
      <div className="flex flex-col gap-4">
        <p className="type-ui text-fg-muted">{e.status}</p>
        {e.lead ? <p className="type-body font-medium text-pretty">{e.lead}</p> : null}
        <table className="w-full border-collapse type-body">
          <thead>
            <tr>
              <th scope="col" colSpan={2} className={cn('border-b border-edge-surface pb-2 text-left type-ui font-regular text-fg-muted', api && 'font-code')}>{itemLabel}</th>
              {hasFigure ? <th scope="col" className={cn('border-b border-edge-surface pb-2 pl-4 text-right type-ui font-regular whitespace-nowrap text-fg-muted', api && 'font-code')}>{figureLabel}</th> : null}
            </tr>
          </thead>
          <tbody>
            {e.rows.map((row, i) => {
              const cell = i === last ? 'pt-3 align-top' : 'border-b border-edge-surface py-3 align-top'
              return (
                <tr key={row.title}>
                  <td className={cn(cell, 'w-16 pr-4')}>
                    {row.creative ? <CreativeCard src={row.creative.src} alt={row.creative.alt ?? ''} fit={row.creative.fit} position={row.creative.position} brand={row.creative.brand} tone={row.creative.tone} ratio="4/5" className="w-12" /> : null}
                  </td>
                  <td className={cell}>
                    <span className="block font-medium">{row.title}</span>
                    <span className="mt-1 block type-ui text-pretty text-fg-soft">{row.detail}</span>
                  </td>
                  {hasFigure ? <td className={cn(cell, 'pl-4 text-right type-body-lg whitespace-nowrap tabular-nums')}>{row.figure}</td> : null}
                </tr>
              )
            })}
          </tbody>
        </table>
        {e.note ? <p className="border-t border-edge-surface pt-4 type-ui text-pretty text-fg-soft">{e.note}</p> : null}
        <p className="flex flex-wrap items-center gap-2 type-ui">
          <span className="text-fg-muted">{callsLabel}</span>
          {e.calls.map((call) => <code key={call} className="rounded-ds-sm bg-surface-inset px-2 py-1 font-code text-fg">{call}</code>)}
        </p>
      </div>
    </div>
  )
}

export default UseCaseAnswer

// The use case answer (site pages/UseCasesPage/UseCaseAnswer): one question (or one API request) and the answer that
// came back, as a raised panel. Both flavors read this file for its types and the Acme examples.
import type { ImageSlot } from '@/lib/image'

export interface AnswerRow {
	title: string
	detail: string
	/** The figure on the right ("71", "84 days"). */
	figure?: string
	/** A creative beside the row: the user's own image (`src`), or a neutral placeholder. */
	creative?: ImageSlot & { brand?: string; tone?: 1 | 2 | 3 | 4 }
}

export interface AnswerExample {
	/** chat (a question in a bubble) or api (the request as code). */
	mode: 'chat' | 'api'
	mention?: string
	question: string
	/** The request, shown in api mode. */
	request?: string
	/** "Worked for 5s", "200 OK in 412ms". */
	status: string
	lead?: string
	/** The item column and, when the rows have figures, the figure column. */
	columns: [string, string?]
	rows: AnswerRow[]
	note?: string
	/** The tools or endpoints called. */
	calls: string[]
}

export const useCaseAnswerChat: AnswerExample = {
	mode: 'chat',
	question: 'What hooks has Acme leaned on in its Meta ads in the last 30 days?',
	status: 'Worked for 5s',
	lead: 'Acme’s Meta ads from Oct 17 to Nov 16 leaned on a handful of repeatable hooks:',
	columns: ['Hook', 'Ads'],
	rows: [
		{ title: 'Mornings without the rush', detail: 'A full breakfast in about a minute.', figure: '71', creative: { brand: 'Acme', tone: 1 } },
		{ title: 'Healthy eating takes effort', detail: 'Skip the meal prep, keep the nutrition.', figure: '64', creative: { brand: 'Acme', tone: 2 } },
		{ title: 'Better value than the usual', detail: '“My breakfast costs less than your coffee.”', figure: '47', creative: { brand: 'Acme', tone: 3 } },
		{ title: 'Try before committing', detail: 'A sampler box takes the risk out of a flavor.', figure: '33', creative: { brand: 'Acme', tone: 4 } },
	],
	note: 'Lead with a familiar friction, then answer it with the nutrition numbers, speed and price. These are the themes that come up again and again, in no ranked order.',
	calls: ['getBrandMediaInsights'],
}

export const useCaseAnswerApi: AnswerExample = {
	mode: 'api',
	question: 'The longest running Meta ads for running shoes',
	request: 'POST /v2/media\n{\n  "accountIds": ["acme-run", "strider", "fleetfoot"],\n  "channel": "META_AD",\n  "sortBy": "LONGEST_RUN",\n  "limit": 3\n}',
	status: '200 OK in 412ms',
	columns: ['media', 'daysActive'],
	rows: [
		{ title: 'Acme Run: the gold racer', detail: 'Video, 15s. Running since Aug 23.', figure: '84 days', creative: { brand: 'Acme Run', tone: 3 } },
		{ title: 'Strider: trail, labelled', detail: 'Image. Running since Sep 15.', figure: '61 days', creative: { brand: 'Strider', tone: 2 } },
		{ title: 'Fleetfoot: on orange', detail: 'Carousel, 4 cards. Running since Sep 29.', figure: '47 days', creative: { brand: 'Fleetfoot', tone: 4 } },
	],
	calls: ['POST /v2/media'],
}

export const useCaseAnswerCallsLabel = 'Called'

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

